import{_ as n,C as i,o as a,c as r,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Instruction Lineage Is Not Instruction Authority","description":"","frontmatter":{"title":"Instruction Lineage Is Not Instruction Authority","date":"2026-08-24","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"When a subagent inherits parent history but receives child-specific developer instructions, how should the architecture preserve instruction lineage without turning provenance labels into implicit authorization?","summary":"A merged Codex change gives child-only developer instructions typed provenance and a tested parent/child boundary. That makes context derivation inspectable, but a separate authority plane is still required to establish who may supply or override instructions.","sources":["research/analysis/Q-20260824-02-instruction-lineage-authority-separation.md"],"item_id":"Q-20260824-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-24-instruction-lineage-not-authority-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-08-24-instruction-lineage-not-authority.md","filePath":"en/industry/2026-08-24-instruction-lineage-not-authority.md","lastUpdated":1787666502000}'),c={name:"en/industry/2026-08-24-instruction-lineage-not-authority.md"};function l(d,e,h,p,u,m){const t=i("ArticleCover");return a(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-08-24-instruction-lineage-not-authority-cover-v2.png",kicker:"Industry Architecture · Daily Research",title:"Instruction Lineage Is Not Instruction Authority",summary:"A merged Codex change gives child-only developer instructions typed provenance and a tested parent/child boundary. That makes context derivation inspectable, but a separate authority plane is still required to establish who may supply or override instructions.",version:"Q-20260824-02",status:"Daily Runtime V5 · 2026-08-24",languageHref:"/zh/industry/2026-08-24-instruction-lineage-not-authority",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="instruction-lineage-is-not-instruction-authority" tabindex="-1">Instruction Lineage Is Not Instruction Authority <a class="header-anchor" href="#instruction-lineage-is-not-instruction-authority" aria-label="Permalink to &quot;Instruction Lineage Is Not Instruction Authority&quot;">​</a></h1><p>A child agent can inherit nearly all of a parent conversation and still need one instruction that belongs only to the child. If that instruction becomes ordinary or unclassified text, the system loses its semantic identity. If it appears in the parent request, the boundary leaks. If it appears twice in the child, the effective context changes again.</p><p>A Codex change merged on 2026-08-24 adds a dedicated <code>DeveloperInstructions</code> contextual fragment with developer role and <code>generic.developer_instructions</code> content kind. In the demonstrated full-history fork, the implementation filters inherited developer material, conditionally supplies the child-only fragment and tests three facts together: the parent excludes the child instruction, the child preserves its classification, and the exact text appears once in child developer messages.</p><p>This strengthens lineage at one real request boundary. It does not prove that the caller was authorized to create the instruction. <strong>Instruction provenance and instruction authority are different control planes.</strong></p><h2 id="typed-context-preserves-semantic-identity" tabindex="-1">Typed context preserves semantic identity <a class="header-anchor" href="#typed-context-preserves-semantic-identity" aria-label="Permalink to &quot;Typed context preserves semantic identity&quot;">​</a></h2><p>Copying text can preserve words while destroying origin. An inherited paragraph, a parent developer rule and a child-local override may look similar after compaction, yet they belong to different derivation paths and scopes.</p><p>The new fragment improves that first layer. Developer guidance is no longer annotated with an unknown content kind on this path. Its role and semantic kind remain inspectable by downstream context construction and request-level tests. That makes it possible to ask whether the material was inherited, introduced locally or substituted at the fork boundary.</p><p>Typed provenance is especially useful when history is transformed. A fork may preserve reference context while replacing parent-specific instructions. Without an explicit fragment identity, text-oriented rewriting has to infer which words constitute control material. The selected code still contains a TODO for more precise message-fragment provenance, so the mechanism should be understood as a partial improvement rather than a complete provenance graph.</p><h2 id="the-fork-must-preserve-both-exclusion-and-representation" tabindex="-1">The fork must preserve both exclusion and representation <a class="header-anchor" href="#the-fork-must-preserve-both-exclusion-and-representation" aria-label="Permalink to &quot;The fork must preserve both exclusion and representation&quot;">​</a></h2><p>A correct child boundary needs two complementary properties. Child-only control must not leak into the parent&#39;s request, and it must remain present in the child exactly where intended. Testing only the child could miss parent contamination; testing only parent exclusion could leave the child without its required guidance.</p><p>The Codex regression inspects actual request surfaces. It verifies the parent does not contain the configured child-only text, the child carries the dedicated content kind, and the exact text count is one among child developer messages. That is stronger evidence than checking only an intermediate object.</p><p>The “once” claim remains local to this request construction. It does not establish deduplication across retries, distributed delivery or replay. The architecture should therefore treat single representation at construction, durable transport identity and replay idempotence as separate guarantees.</p><h2 id="a-developer-label-cannot-authorize-its-own-source" tabindex="-1">A developer label cannot authorize its own source <a class="header-anchor" href="#a-developer-label-cannot-authorize-its-own-source" aria-label="Permalink to &quot;A developer label cannot authorize its own source&quot;">​</a></h2><p>Role ordering and provenance solve different problems from permission. A developer-role instruction may legitimately rank above conversational user content in a model request. That fact says what the instruction is and how the model should interpret it. It does not say which principal was permitted to create it, whether an external policy allowed the override or how long that authority remains valid.</p><p>A robust design needs an authority record that binds principal, policy source, scope, freshness and any delegation chain. The lineage plane can then say, “this fragment is child-local developer guidance derived at fork X.” The authority plane must separately say, “principal Y was allowed by policy Z to supply this guidance for scope S.”</p><p>Collapsing both into the developer label creates privilege drift. A fragment can retain a high-precedence role while moving through fork, compaction or replay, even if the authorization context that originally allowed it no longer applies.</p><h2 id="lifecycle-transitions-must-declare-what-happens-to-control" tabindex="-1">Lifecycle transitions must declare what happens to control <a class="header-anchor" href="#lifecycle-transitions-must-declare-what-happens-to-control" aria-label="Permalink to &quot;Lifecycle transitions must declare what happens to control&quot;">​</a></h2><p>Fork is only the first transformation. Compaction can summarize away boundaries. Resume can reload older effective context under a changed policy. Replay can deliver the same fragment into a new execution. Each transition should state whether instruction lineage is preserved, transformed or replaced—and whether authority is still valid or must be re-established.</p><p>Low-risk, single-process systems may trust the caller that constructs every child. That can be a reasonable simplification, but it is a stated trust assumption, not evidence contained in the provenance label.</p><p>The practical audit test has two columns: where did every effective instruction come from, and which principal or policy allowed it to apply here? A system that can answer only the first has lineage. A system that infers the second from a role label has confused provenance with authority.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/openai/codex/commit/a70974c1a0837e17769e3c41f83ad5e592c703fb" target="_blank" rel="noreferrer">OpenAI Codex merged commit a70974c1</a>. The code and request-level regression support the bounded child-instruction behavior described here; they are not independent proof of authenticated authority or end-to-end policy integrity.</p>',21))])}const v=n(c,[["render",l]]);export{g as __pageData,v as default};
